import{_ as t,c as e,o as r,b2 as s}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"C7Watermark（C7 水印）设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-08-c7-watermark-design.md","filePath":"superpowers/specs/2026-05-08-c7-watermark-design.md"}'),n={name:"superpowers/specs/2026-05-08-c7-watermark-design.md"};function d(c,o,a,g,i,l){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="c7watermark-c7-水印-设计说明" tabindex="-1">C7Watermark（C7 水印）设计说明 <a class="header-anchor vp-link" href="#c7watermark-c7-水印-设计说明" aria-label="Permalink to &quot;C7Watermark（C7 水印）设计说明&quot;">​</a></h1><p><strong>日期</strong>：2026-05-08<br><strong>状态</strong>：已定稿（经 brainstorming 澄清与「整稿确认」）<br><strong>依据</strong>：<code>原始需求/前端/C7水印.md</code> + Q&amp;A 结论（1B、2C、3B、4C、5A）及路径 <strong>B</strong>（<code>index.vue</code> + 同目录纯函数模块）</p><hr><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>后台系统需在<strong>页面区域或全屏</strong>叠加水印（用户名 / 部门 / 时间等），降低截图泄露风险；支持<strong>文本与图片</strong>、可配置旋转 / 间距 / 透明度 / <code>z-index</code>，并可选<strong>防删除</strong>（DOM 被改后自动恢复）。</p><p><strong>非目标</strong>：水印密码学强度、防专业截屏工具、服务端鉴权；本期不承诺「水印上再放可点击子元素」。</p><hr><h2 id="_2-组件边界" tabindex="-1">2. 组件边界 <a class="header-anchor vp-link" href="#_2-组件边界" aria-label="Permalink to &quot;2. 组件边界&quot;">​</a></h2><ul><li><strong>职责</strong>：在<strong>容器内</strong>或<strong>视口 / 文档级全屏</strong>上叠一层<strong>可穿透点击</strong>的水印图案（Canvas 生成重复 tile 后应用到水印层）。</li><li><strong>与 Element Plus</strong>：<strong>不自研替代 <code>ElWatermark</code> 的对外 API</strong>；本期 <strong>5A</strong> 为<strong>自研 Canvas 拼 tile</strong>，不依赖 EP 水印组件封装。</li><li><strong>集成（1B）</strong>：交付组件 + <strong>VitePress 文档</strong>（含 <strong>Layout 级全屏水印示例片段</strong>）；<strong>不强制</strong>修改项目默认 Layout，由业务按需接入。</li></ul><hr><h2 id="_3-技术选型与文件结构" tabindex="-1">3. 技术选型与文件结构 <a class="header-anchor vp-link" href="#_3-技术选型与文件结构" aria-label="Permalink to &quot;3. 技术选型与文件结构&quot;">​</a></h2><ul><li><strong>实现路径</strong>：<strong>路径 B</strong> — <code>quick-ui/src/packages/C7Watermark/index.vue</code> + 同目录 <strong><code>buildWatermarkPattern.js</code></strong>（或等价命名）承载<strong>纯函数</strong>（根据参数生成图案 <code>dataURL</code>、tile 尺寸等），便于阅读与单测；<strong>不</strong>引入独立 composable 目录以免 YAGNI。</li><li><strong>绘制策略</strong>：<strong>离屏 Canvas</strong> 生成<strong>小块重复图案</strong>，导出 <strong><code>dataURL</code></strong>，水印层使用 <strong><code>background-image</code> + <code>repeat</code></strong>（或等价）铺满；避免整页单张超大 Canvas。</li><li><strong>图片与跨域（3B）</strong>：通过 prop 暴露 <strong><code>crossOrigin</code></strong>（<code>&#39;&#39;</code> / <code>&#39;anonymous&#39;</code> / <code>undefined</code> 等由业务传入）；加载或绘制失败时<strong>回落为 <code>text</code></strong>。文档须说明：外链需服务端正确 CORS，否则可能无法读像素。</li></ul><hr><h2 id="_4-布局模式-含-2c" tabindex="-1">4. 布局模式（含 2C） <a class="header-anchor vp-link" href="#_4-布局模式-含-2c" aria-label="Permalink to &quot;4. 布局模式（含 2C）&quot;">​</a></h2><h3 id="_4-1-容器模式-默认" tabindex="-1">4.1 容器模式（默认） <a class="header-anchor vp-link" href="#_4-1-容器模式-默认" aria-label="Permalink to &quot;4.1 容器模式（默认）&quot;">​</a></h3><ul><li>根节点 <strong><code>position: relative</code></strong>，<strong>默认插槽</strong>为业务内容。</li><li>水印层子元素：<strong><code>position: absolute; inset: 0</code></strong>，叠在内容之上；<strong><code>pointer-events: none</code></strong>、<strong><code>user-select: none</code></strong>（默认定稿；若与极少数业务冲突，实现阶段可再评估是否增加 prop，<strong>本设计默认不写</strong>）。</li></ul><h3 id="_4-2-全屏模式" tabindex="-1">4.2 全屏模式 <a class="header-anchor vp-link" href="#_4-2-全屏模式" aria-label="Permalink to &quot;4.2 全屏模式&quot;">​</a></h3><ul><li><strong><code>fullscreen === true</code></strong>：水印层 <strong><code>position: fixed</code></strong>，<strong><code>z-index</code></strong> 来自 prop。</li><li><strong><code>fullscreenScope</code></strong>（新增，对应 <strong>2C</strong>）： <ul><li><strong><code>&#39;viewport&#39;</code></strong>：覆盖当前视口（如 <code>inset: 0</code> 或等价 <code>100dvh</code> / <code>100vw</code> 语义），不随文档超出视口部分延伸。</li><li><strong><code>&#39;document&#39;</code></strong>：覆盖<strong>整份可滚动文档</strong>高度（长页不露底）；水印层高度随 <strong><code>document.documentElement</code>（或约定根）滚动高度</strong>更新，并监听 <strong><code>resize</code></strong>，必要时对文档根使用 <strong><code>ResizeObserver</code></strong> 与窗口尺寸变化合并更新。</li></ul></li></ul><hr><h2 id="_5-内容与绘制规则" tabindex="-1">5. 内容与绘制规则 <a class="header-anchor vp-link" href="#_5-内容与绘制规则" aria-label="Permalink to &quot;5. 内容与绘制规则&quot;">​</a></h2><ul><li><strong>水印内容优先级</strong>：若配置了 <strong><code>image</code></strong> 且加载 / 绘制成功，则使用<strong>图片 tile</strong>；否则使用 <strong><code>text</code></strong>（<code>string</code> 或 <strong><code>string[]</code></strong> 多行）。</li><li><strong><code>disabled === true</code></strong>：<strong>不渲染</strong>水印层，<strong>不</strong>注册 <code>MutationObserver</code> 或其它副作用监听。</li><li><strong>Props 变化</strong>：依赖图案的 props 变化时<strong>重绘</strong>；实现侧使用 <strong><code>requestAnimationFrame</code> 合并</strong>或短<strong>防抖</strong>，避免窗口连续 <code>resize</code> 时频繁 <strong><code>toDataURL</code></strong>。</li><li><strong><code>image</code> URL 变化</strong>：通过递增 <strong>token</strong> 或等价方式忽略<strong>过期异步回调</strong>，避免竞态覆盖。</li></ul><hr><h2 id="_6-防删除-4c" tabindex="-1">6. 防删除（4C） <a class="header-anchor vp-link" href="#_6-防删除-4c" aria-label="Permalink to &quot;6. 防删除（4C）&quot;">​</a></h2><ul><li><strong>主语义</strong>：<strong><code>tamperResistant</code></strong>，<code>boolean</code>，默认 <strong><code>false</code></strong>。为 <strong><code>true</code></strong> 时使用 <strong><code>MutationObserver</code></strong>（及必要时与<strong>子树</strong>相关的配置）监视水印节点被移除或从约定父节点脱离等情况，<strong>自动恢复</strong>（重新挂载节点并触发重绘流程）。</li><li><strong>兼容别名</strong>：<strong><code>editable</code></strong>（与原始需求文档一致）。<strong><code>editable === false</code></strong> 等价于开启防删逻辑。</li><li><strong>同时传入</strong>：若 <strong><code>tamperResistant</code> 显式传入</strong>（含 <code>true</code> / <code>false</code>），<strong>以 <code>tamperResistant</code> 为准</strong>；<strong>仅传 <code>editable</code></strong> 时按上条映射。文档表格中写明优先级，避免误用。</li><li><strong>卸载</strong>：<strong><code>onBeforeUnmount</code></strong> 中断开 <strong>observer</strong>、移除 <strong>resize / ResizeObserver / rAF</strong> 等监听。</li></ul><hr><h2 id="_7-对外-api-概要" tabindex="-1">7. 对外 API 概要 <a class="header-anchor vp-link" href="#_7-对外-api-概要" aria-label="Permalink to &quot;7. 对外 API 概要&quot;">​</a></h2><h3 id="_7-1-命名与注册" tabindex="-1">7.1 命名与注册 <a class="header-anchor vp-link" href="#_7-1-命名与注册" aria-label="Permalink to &quot;7.1 命名与注册&quot;">​</a></h3><ul><li>组件名：<strong><code>C7Watermark</code></strong></li><li>路径：<code>quick-ui/src/packages/C7Watermark/index.vue</code>（+ <code>buildWatermarkPattern.js</code>）</li><li>在 <strong><code>quick-ui/src/packages/index.js</code></strong> 中 <strong>export</strong> 与 <strong><code>installPackages</code></strong> 注册。</li></ul><h3 id="_7-2-props-与原始需求对齐并扩展" tabindex="-1">7.2 Props（与原始需求对齐并扩展） <a class="header-anchor vp-link" href="#_7-2-props-与原始需求对齐并扩展" aria-label="Permalink to &quot;7.2 Props（与原始需求对齐并扩展）&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>Prop</th><th>类型 / 约束</th><th>说明</th></tr></thead><tbody><tr><td><strong><code>text</code></strong></td><td><code>string | string[]</code></td><td>文本或多行；图片失败时回落。</td></tr><tr><td><strong><code>image</code></strong></td><td><code>string</code>（URL）</td><td>优先；失败回落 <code>text</code>。</td></tr><tr><td><strong><code>fullscreen</code></strong></td><td><code>boolean</code>，默认 <code>false</code></td><td>全屏 vs 容器模式。</td></tr><tr><td><strong><code>fullscreenScope</code></strong></td><td><code>&#39;viewport&#39; | &#39;document&#39;</code></td><td>仅 <strong><code>fullscreen=true</code></strong> 时生效；默认 <strong><code>&#39;viewport&#39;</code></strong>（实现须在文档中写明）。</td></tr><tr><td><strong><code>disabled</code></strong></td><td><code>boolean</code></td><td><code>true</code> 不渲染水印。</td></tr><tr><td><strong><code>tamperResistant</code></strong></td><td><code>boolean</code></td><td>防删；与 <code>editable</code> 优先级见 §6。</td></tr><tr><td><strong><code>editable</code></strong></td><td><code>boolean</code></td><td>兼容：<strong><code>false</code> ⇒ 防删</strong>；与 <code>tamperResistant</code> 同时存在时 <strong><code>tamperResistant</code> 优先</strong>。</td></tr><tr><td><strong><code>zIndex</code></strong></td><td><code>number</code></td><td>全屏 / 叠层层级。</td></tr><tr><td><strong><code>crossOrigin</code></strong></td><td><code>string | undefined</code></td><td>图片 <strong><code>HTMLImageElement.crossOrigin</code></strong>；业务按 CDN 配置。</td></tr><tr><td><strong>画布 / 样式</strong></td><td>—</td><td><strong><code>fontSize</code> / <code>fontColor</code> / <code>fontFamily</code> / <code>opacity</code> / <code>rotate</code> / <code>gapX</code> / <code>gapY</code> / <code>width</code> / <code>height</code> / <code>offsetX</code> / <code>offsetY</code></strong> 与原始需求一致；默认值在实现 JSDoc 与文档中列出。</td></tr></tbody></table></div><p>根节点 <strong><code>class</code> / <code>style</code></strong> 透传策略与现有 C7 组件对齐（如 <strong><code>defineOptions({ inheritAttrs: true })</code></strong> 绑定根或水印层策略在实现时二选一并写入 JSDoc，<strong>须</strong>与「水印层不挡点击」不冲突）。</p><hr><h2 id="_8-验收标准-与原始需求对齐" tabindex="-1">8. 验收标准（与原始需求对齐） <a class="header-anchor vp-link" href="#_8-验收标准-与原始需求对齐" aria-label="Permalink to &quot;8. 验收标准（与原始需求对齐）&quot;">​</a></h2><ul><li><strong>文本 / 图片</strong>均可生成<strong>可见的重复背景</strong>；图片失败时可见<strong>文本</strong>回落。</li><li><strong><code>fullscreenScope</code></strong>：<code>viewport</code> 与 <code>document</code> 在长页场景下行为符合 §4.2。</li><li><strong><code>tamperResistant === true</code></strong> 或 <strong><code>editable === false</code></strong>（且未被 <code>tamperResistant</code> 覆盖）时，<strong>手动删除水印层 DOM</strong> 后<strong>自动恢复</strong>。</li><li><strong><code>disabled=true</code></strong> 时无水印层、无 observer。</li><li><strong>卸载</strong>后无残留监听。</li></ul><hr><h2 id="_9-文档与示例-1b" tabindex="-1">9. 文档与示例（1B） <a class="header-anchor vp-link" href="#_9-文档与示例-1b" aria-label="Permalink to &quot;9. 文档与示例（1B）&quot;">​</a></h2><ul><li><strong>VitePress</strong>：新增 C7Watermark 说明页 — props 表、<code>fullscreenScope</code>、<code>crossOrigin</code>、防删语义、容器 / 全屏示例。</li><li><strong>Layout 片段</strong>：文档中提供「在根 Layout 套一层全屏水印、从 store / 用户信息拼 <code>text</code>」的<strong>可复制示例</strong>，<strong>不</strong>作为仓库默认改动的硬性要求。</li></ul><hr><h2 id="_10-测试建议-实现阶段" tabindex="-1">10. 测试建议（实现阶段） <a class="header-anchor vp-link" href="#_10-测试建议-实现阶段" aria-label="Permalink to &quot;10. 测试建议（实现阶段）&quot;">​</a></h2><ul><li><strong>Dev 演示页</strong>（若项目惯例存在 <code>C7*E2E.vue</code>）：文本 / 图片、两种 <code>fullscreenScope</code>、防删手动验收。</li><li><strong>自动化</strong>：以 <strong>E2E 或 smoke</strong> 为主（例如删除水印节点后断言层仍存在或可恢复）；<strong>不做</strong>整页像素级 Canvas 断言（非必须）。</li></ul><hr><h2 id="_11-修订记录" tabindex="-1">11. 修订记录 <a class="header-anchor vp-link" href="#_11-修订记录" aria-label="Permalink to &quot;11. 修订记录&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>日期</th><th>说明</th></tr></thead><tbody><tr><td>2026-05-08</td><td>初版：brainstorming 澄清与整稿确认后落盘。</td></tr></tbody></table></div>',43)])])}const p=t(n,[["render",d]]);export{u as __pageData,p as default};
